-- WG-5. Rows created before 0063 keep canonical_repo and unit NULL.
-- Fill only when id and repo are the lowercase hex SHA-256 of the length-prefixed task and agent.
-- The prefix uses character length, which matches JS String.length for BMP identifiers.
-- D1 has no sha256(), so this file recomputes SHA-256 over the UTF-8 message bytes.
-- A row whose recomputed digest is not id stays NULL. The guard reads only rows whose
-- recomputed digest equals id, so an unverified NULL does not abort the file.
CREATE TABLE wrgit_0068_msg (id TEXT PRIMARY KEY, pad TEXT NOT NULL, nblocks INTEGER NOT NULL);
INSERT INTO wrgit_0068_msg (id, pad, nblocks)
SELECT id, pad, nblocks FROM (
  SELECT id,
    hx || '80' || hex(zeroblob(CASE WHEN nbytes % 64 <= 55 THEN 55 - (nbytes % 64) ELSE 119 - (nbytes % 64) END))
      || '00000000' || printf('%08X', nbytes * 8) AS pad,
    (nbytes + 9 + 63) / 64 AS nblocks
  FROM (
    SELECT id, hex(blob) AS hx, length(blob) AS nbytes
    FROM (
      SELECT id,
        cast(printf('%d:', length(task_id)) || task_id || printf('%d:', length(agent_id)) || agent_id AS blob) AS blob
      FROM wrgit_workspaces
      WHERE (canonical_repo IS NULL OR unit IS NULL)
        AND id = repo
        AND length(id) = 64
        AND id NOT GLOB '*[^0-9a-f]*'
    )
  )
)
WHERE nblocks BETWEEN 1 AND 6;
