UPDATE wrgit_workspaces
SET canonical_repo = COALESCE(canonical_repo, 'main/agent-workroom'),
    unit = COALESCE(unit, task_id)
WHERE (canonical_repo IS NULL OR unit IS NULL)
  AND id IN (SELECT id FROM wrgit_0068_digest);
CREATE TABLE wrgit_0068_backfill_guard (ok INTEGER NOT NULL);
CREATE TRIGGER wrgit_0068_backfill_guard_fail BEFORE INSERT ON wrgit_0068_backfill_guard WHEN NEW.ok != 1 BEGIN SELECT RAISE(ABORT, 'Workspace canonical_repo or unit cannot be derived from the stored row.'); END;
INSERT INTO wrgit_0068_backfill_guard (ok)
SELECT CASE WHEN EXISTS (
  SELECT 1 FROM wrgit_workspaces w
  INNER JOIN wrgit_0068_digest d ON d.id = w.id AND d.digest = w.id
  WHERE w.canonical_repo IS NULL OR w.unit IS NULL
    OR length(w.canonical_repo) < 1 OR length(w.canonical_repo) > 200
    OR length(w.unit) < 1 OR length(w.unit) > 128
) THEN 0 ELSE 1 END;
DROP TABLE wrgit_0068_backfill_guard;
DROP TABLE wrgit_0068_digest;
